module scroll_code_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] grid [0:2][0:2],\n    output reg [15:0] result,\n    output reg done\n);\n    // State definitions\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] INIT      = 3'd1;\n    localparam [2:0] ENUMERATE = 3'd2;\n    localparam [2:0] CHECK     = 3'd3;\n    localparam [2:0] INCREMENT = 3'd4;\n    localparam [2:0] FINISH    = 3'd5;\n    \n    reg [2:0] state;\n    reg [2:0] next_state;\n    reg [3:0] temp_grid [0:2][0:2];\n    \n    // Zero position tracking\n    reg [1:0] zero_rows [0:3];\n    reg [1:0] zero_cols [0:3];\n    reg [2:0] num_zeros;\n    reg [12:0] comb_index;       // Up to 9^4=6561 combinations\n    reg [12:0] comb_max;\n    reg [3:0] current_vals [0:3];\n    \n    // Checking variables\n    reg valid_combo;\n    reg [1:0] check_row;\n    reg [1:0] check_col;\n    \n    reg [15:0] cycle_count;\n    localparam [15:0] MAX_CYCLES = 16'd10000;\n    \n    integer i, j, k;  // Loop counters\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 16'd0;\n            done <= 1'b0;\n            cycle_count <= 16'd0;\n            comb_index <= 13'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                zero_rows[i] <= 2'd0;\n                zero_cols[i] <= 2'd0;\n                current_vals[i] <= 4'd0;\n            end\n            num_zeros <= 3'd0;\n            comb_max <= 13'd0;\n            valid_combo <= 1'b0;\n            check_row <= 2'd0;\n            check_col <= 2'd0;\n            for (i = 0; i < 3; i = i + 1) begin\n                for (j = 0; j < 3; j = j + 1) begin\n                    temp_grid[i][j] <= 4'd0;\n                end\n            end\n        end else begin\n            cycle_count <= cycle_count + 16'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 16'd0;\n                    comb_index <= 13'd0;\n                    if (start) begin\n                        state <= INIT;\n                        cycle_count <= 16'd0;\n                    end\n                end\n                \n                INIT: begin\n                    // Find zero positions\n                    num_zeros <= 3'd0;\n                    for (i = 0; i < 3; i = i + 1) begin\n                        for (j = 0; j < 3; j = j + 1) begin\n                            temp_grid[i][j] <= grid[i][j];\n                            if (grid[i][j] == 4'd0) begin\n                                zero_rows[num_zeros] <= i[1:0];\n                                zero_cols[num_zeros] <= j[1:0];\n                                num_zeros <= num_zeros + 3'd1;\n                            end\n                        end\n                    end\n                    // Calculate max combinations (9^num_zeros)\n                    comb_max <= (num_zeros == 3'd0) ? 13'd0 : 13'd1;\n                    for (k = 0; k < num_zeros; k = k + 1) begin\n                        comb_max <= comb_max * 13'd9;\n                    end\n                    state <= ENUMERATE;\n                end\n                \n                ENUMERATE: begin\n                    // Apply current combination to temp_grid\n                    for (k = 0; k < num_zeros; k = k + 1) begin\n                        current_vals[k] <= (comb_index / (9**k)) % 13'd9 + 4'd1;\n                        temp_grid[zero_rows[k]][zero_cols[k]] <= current_vals[k];\n                    end\n                    valid_combo <= 1'b1;\n                    check_row <= 2'd0;\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    // Check row uniqueness\n                    for (i = 0; i < 3; i = i + 1) begin\n                        for (j = 0; j < 3; j = j + 1) begin\n                            for (k = j + 1; k < 3; k = k + 1) begin\n                                if (temp_grid[i][j] == temp_grid[i][k])\n                                    valid_combo <= 1'b0;\n                            end\n                        end\n                    end\n                    \n                    // Check L-shape constraints\n                    for (i = 1; i < 3; i = i + 1) begin\n                        for (j = 0; j < 2; j = j + 1) begin\n                            if (temp_grid[i][j] == 4'd0 || temp_grid[i][j+1] == 4'd0 || temp_grid[i-1][j] == 4'd0) begin\n                                valid_combo <= 1'b0;\n                            end else begin\n                                // l = current cell, r = right neighbor, u = upper cell\n                                reg [7:0] l, r, u;\n                                reg valid_op;\n                                l = temp_grid[i][j];\n                                r = temp_grid[i][j+1];\n                                u = temp_grid[i-1][j];\n                                valid_op = 1'b0;\n                                \n                                // Check possible operations\n                                if ((l * r) == u) valid_op = 1'b1;\n                                else if ((l + r) == u) valid_op = 1'b1;\n                                else if ((l > r) ? (l - r) : (r - l)) == u) valid_op = 1'b1;\n                                else if (r != 0 && l % r == 0 && (l / r) == u) valid_op = 1'b1;\n                                else if (l != 0 && r % l == 0 && (r / l) == u) valid_op = 1'b1;\n                                \n                                if (!valid_op) valid_combo <= 1'b0;\n                            end\n                        end\n                    end\n                    \n                    // Increment count if valid\n                    if (valid_combo) result <= result + 16'd1;\n                    state <= INCREMENT;\n                end\n                \n                INCREMENT: begin\n                    comb_index <= comb_index + 13'd1;\n                    if (comb_index == comb_max - 13'd1 || cycle_count >= MAX_CYCLES - 13'd5) begin\n                        state <= FINISH;\n                    end else begin\n                        state <= ENUMERATE;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule